internal sealed class GameItem{public int Id;string text;public GameItem(Process p){Id=p.Id;text=(string.IsNullOrWhiteSpace(p.MainWindowTitle)?"ElementClient":p.MainWindowTitle)+" · PID "+p.Id;}public override string ToString(){return text;}}
